package com.animame.editor

import kotlin.math.*

enum class BrushAlgorithm { MONO, WATER, DOUBLE, COLOR, AIRBRUSH, PARTICLE, BLUR, ERASER, VECTOR }

enum class BrushCategory { INK, SKETCH, WATERCOLOUR, PAINT, MARKER, PASTEL, CHARCOAL, EFFECTS, LIGHT, PLANTS, MATERIALS, HAIR, COMIC, DIGITAL, POINTILLISM, STAMP, ERASER, VECTOR, OTHER }

data class CurvePoint(val x: Float, val y: Float)
data class PressureCurve(val points: List<CurvePoint> = listOf(CurvePoint(0f,0f), CurvePoint(0.5f,0.5f), CurvePoint(1f,1f))) {
    fun eval(v: Float): Float { val x=v.coerceIn(0f,1f); val p=points.sortedBy{it.x}; for(i in 0 until p.lastIndex) if(x<=p[i+1].x){val t=((x-p[i].x)/(p[i+1].x-p[i].x).coerceAtLeast(1e-5f)); return p[i].y+(p[i+1].y-p[i].y)*t}; return p.last().y }
}

data class BrushSettings(
    val id:String,val name:String,val category:BrushCategory,val algorithm:BrushAlgorithm,
    val size:Float=12f,val opacity:Float=1f,val minSize:Float=0.05f,val maxSize:Float=1f,
    val fadeStart:Float=0f,val fadeEnd:Float=1f,val spacing:Float=0.18f,val aspect:Float=1f,val angle:Float=0f,val rotationFollow:Float=1f,
    val jitterPosition:Float=0f,val jitterSize:Float=0f,val jitterOpacity:Float=0f,val jitterRotation:Float=0f,val scatter:Float=0f,val particleDensity:Float=1f,val particleSize:Float=1f,
    val blur:Float=0f,val texture:Float=0f,val textureScale:Float=1f,val wetness:Float=0f,val colorMix:Float=0f,val dragging:Float=0f,
    val pressureSize:Float=0f,val pressureOpacity:Float=0f,val speedSize:Float=0f,val speedOpacity:Float=0f,
    val pressureCurveSize:PressureCurve=PressureCurve(),val pressureCurveOpacity:PressureCurve=PressureCurve(),val blendMode:String="SRC_OVER",
    val invert:Boolean=false,val lockSizeOpacity:Boolean=false,val thinSpacing:Boolean=false,val antialias:Boolean=true,val pattern:String="circle",
    val colorJitterHue:Float=0f,val colorJitterSaturation:Float=0f,val colorJitterBrightness:Float=0f,val useCurrentColor:Boolean=true
){ fun normalized()=copy(size=size.coerceIn(.1f,512f),opacity=opacity.coerceIn(0f,1f),minSize=minSize.coerceIn(0f,1f),maxSize=maxSize.coerceIn(.01f,2f),spacing=spacing.coerceIn(.01f,4f),aspect=aspect.coerceIn(.05f,8f),particleDensity=particleDensity.coerceIn(.05f,20f),particleSize=particleSize.coerceIn(.05f,8f),textureScale=textureScale.coerceIn(.05f,20f)) }

object BrushDefaults { fun forPreset(id:String):BrushSettings=BrushCatalog.byId(id).settings }

object BrushCatalog {
    data class Preset(val id:String,val name:String,val settings:BrushSettings)
    private val names = listOf("Dip Pen (Soft)","Dip Pen (Hard)","Dip Pen (Bleed)","Felt Tip Pen (Soft)","Felt Tip Pen (Hard)","Digital Pen","Airbrush (Normal)","Airbrush (Triangle)","Airbrush (Trapezoid 20%)","Airbrush (Trapezoid 40%)","Airbrush (Trapezoid 60%)","Airbrush (Particle)","Airbrush (Particle L)","Pencil (#1)","Pencil (#2)","Pencil (Graphite)","Watercolor (Real)","Watercolor (Point)","Watercolor (Bleed)","Oil (Rough)","Oil (Hair)","Oriental (Shan Shui)","Round Brush (Point)","Round Brush (Normal)","Round Brush (Curve)","Round Brush (Angle)","Round Brush (Fan)","Round Brush (Real)","Round Brush (Rough)","Round Brush (Particle)","Flat Brush (Point)","Flat Brush (Normal)","Flat Brush (Curve)","Flat Brush (Angle)","Flat Brush (Fan)","Flat Brush (Real)","Flat Brush (Line)","Marker","Five Lines","Charcoal","Soft Pastel","Hard Pastel","Crayon","Chalk","Net1","Net2","Net3","Net4","Circular Cross Hatching","Flash","Wedge","Pile","Speed","Splash","Circle (Edge)","Flare","Light 4","Light 6","Light 8","Heart","Star","Star (Round)","Triangle","Triangle (Noise)","Pentagon","Hexagon","Blur Circle (In)","Blur Circle (Out)","Blur Pentagon (In)","Blur Pentagon (Out)","Eighth Note","Doublet Note","Snow1","Snow2","Petal","Petal (Outline)","Cherry Blossom","Cherry Blossom (Outline)","Chrysanthemum","Chrysanthemum (Outline)","Ume Blossom","Ume Blossom (Outline)","Balloon Flower","Balloon Flower (Outline)","Morning Glory","Morning Glory (Outline)","Peony","Peony (Outline)","Rose","Rose (Outline)","Leaf","Leaf (Outline)","Ginkgo","Ginkgo (Outline)","Maple","Maple (Outline)","Wood Sorrel","Wood Sorrel (Outline)","Clover","Clover (Outline)","Pen (Fade)","Chain 1","Lace","Feather","Swallowtail","Spider Net","Waterwheel","Waterwheel (Outline)","Gear Wheel1","Gear Wheel1 (Outline)","Gear Wheel2","Gear Wheel2 (Outline)","Pinwheel","Pinwheel (Outline)","Square","Pentagram1","Pentagram2","Pentagram3","Hexagram1","Hexagram2","Hexagram3","Calligraphy","Light Diamond","Light Diamond (Outline)","Diamond (Real Top)","Diamond (Real Side)","Diamond (Icon)","Queen Crown","Queen Crown (Outline)","King Crown","King Crown (Outline)","Drop","Drop (Outline)","Dragonfly","Dragonfly (Outline)","Grass (Fern)","Grass (Green foxtail)","Grass (Sedge)","Grass (Nutsedge)","Grass (Goosegrass)","Grass (Kentucky Bluegrass)","Grass (Luzula)","Watercolor (Mix)","Watercolor (Water)","Watercolor (Opaque)","Outline","Light","Flat Watercolor (Mix)","Flat Watercolor (Water)","Flat Watercolor (Opaque)","One Stroke Dragon","Cat Footprint","Cat Footprint (Outline)","Cat Footprints","Cat Footprints (Outline)","Pasta 1","Pasta 2","Pasta 3","Pasta 4","Beads (Normal)","Beads (Thickness)","Hose","Rainbow","Sparkler","Flower Shower","Leaf Shower","Fur 1","Fur 2","Pencil (Rough)","Blurring Brush 1","Blurring Brush 2","Blurring Brush 3","Blurring Brush 4","Blurring Brush 5","Blurring Marker 1","Blurring Marker 2","Love Pen","Ink Pen","Texture Pen","Hair","Glitter 1","Glitter 2","Glitter 3","Glitter 4","Glitter 5","Glitter 6","Bone","Moire 1","Moire 2","Hatching Mod 1","Hatching Mod 2","Pencil Mod (#1)","Pencil Mod (#2)","Pencil Mod (#3)","Mechanical Pencil (#1)","Mechanical Pencil (#2)","Mechanical Pencil (#3)","Colored Pencil","Watercolor Pencil","Ripple Marks","Dot","Grid Dot","Edge Dot","Round Dot","Soft Mapping Pen (Bleed)","Hard Mapping Pen (Smooth)","Soft Turnip Pen (Bleed)","Hard Turnip Pen (Smooth)","Soft School Pen (Bleed)","Hard School Pen (Smooth)","Soft Dip Pen (Bleed)","Hard Dip Pen (Smooth)","Soft Japanese Pen (Bleed)","Hard Japanese Pen (Smooth)","Soft Falcon Pen (Bleed)","Hard Falcon Pen (Smooth)","Technical Pen","Ruling Pen","Drawing Pen","Ballpoint Pen","Water-based Ballpoint Pen","Fountain Pen","Glass Pen","Uniform Eraser (Overlay)","Uniform Eraser (Saturation)","Soft Behind Pen (Bleed)","Hard Behind Pen (Smooth)","Outline (Fade)","Color Outline (Thick)","Color Outline (Middle)","Color Outline (Thin)","Shadow Text","Pointillism 1","Pointillism 2","Pointillism 3","Pointillism 4","Pointillism 5","Pointillism 6","Crayon Mod","Alcohol Marker (Round)","Alcohol Marker (Flat)","Soft Pastel Mod","Hard Pastel Mod","Oil Pastel","Pan Pastel","Charcoal Mod","Fade Watercolor (Mix)","Fade Watercolor (Water)","Fade Watercolor (Opaque)","Impressionism 1","Impressionism 2","Oil (Soft)","Oil (Hard)","Knitting","Knitting (Color Change)","Knitting (Gradation)","Glitter Heart","Sputtering 1","Sputtering 2","Gauze","Hair (Light)","Hair (Dark)","Blurring Outline","Light (Pale)","With Holes","With Holes (Outline)","Vertical Stripes","Horizontal Stripes","Dot Pen","Orthogonal Cross","Diagonal Cross","Grid","Houndstooth","Blurring Square","Only Outline (Part)","Only Outline (Connect)","Tube Pen","Diagonal Shadow Pen","Braid (White)","Braid (Pale)","Braid (Light)","Braid (Vivid)","Braid (Dark)","Stitch (Thick)","Stitch (Middle)","Stitch (Thin)","Stitch (Frame)","Stitch (Line)","Clouds (Real)","Clouds (Cotton)","Clouds (Scale)","Fluffy Watercolor (Mix)","Fluffy Watercolor (Water)","Fluffy Watercolor (Opaque)","Transparent Watercolor (Mix)","Transparent Watercolor (Water)","Transparent Watercolor (Opaque)","Gouache (Mix)","Gouache (Water)","Gouache (Opaque)","Acrylic (Mix)","Acrylic (Water)","Acrylic (Opaque)","Dashed Line","Dotted Line (Square)","Dotted Line (Round)","Watercolor (Edge)","Neon 1","Neon 2","Glitter Dot","Cube Pen","Fastener","Genius Pen","Stylish Marker","Rough Layout Pen (Blurring)","Frizzily Pen","Glitter Pen","Scribble Brush","Scribble Pen","Fashionable Pen","Stylish Pen","Stylish Brush","Prism Ring","Prism Piece","Prism Flash","Japanese Calligraphy (Blurring)","Japanese Calligraphy","Sequin Pen","Sequin Pen (Hexagon)","Sequin Pen (Star)","Sequin Pen (Heart)","Hair Gloss 1","Hair Gloss 2","Three Strand Braid","Three Strand Braid (Outline)","Four Strand Braid","Four Strand Braid (Outline)","Grass (Fern, Color)","Grass (Green foxtail, Color)","Grass (Sedge, Color)","Grass (Nutsedge, Color)","Grass (Goosegrass, Color)","Grass (Kentucky Bluegrass, Color)","Grass (Luzula, Color)","Leaves 1","Leaves 2","Leaf (Color)","Tree 1","Tree 2","Trunk 1","Chain 2 (Color)","Chain 2 (Outline, Color)","Chain 3 (Color)","Chain 3 (Outline, Color)","Chain 4 (Color)","Chain 4 (Outline, Color)","Chain 5 (Color)","Chain 5 (Outline, Color)","Chain 6 (Color)","Chain 6 (Outline, Color)","Chain 7 (Color)","Chain 7 (Outline, Color)","Chain 8 (Color)","Chain 8 (Outline, Color)","Hard (Edge)","Watercolor (Edge 2)","Watercolor (Edge 3)","Watercolor (Mix 2)","Watercolor (Opaque 2)","Flat Watercolor (Mix 2)","Flat Watercolor (Opaque 2)","Fade Watercolor (Opaque 2)","Fluffy Watercolor (Mix 2)","Fluffy Watercolor (Opaque 2)","Transparent Watercolor (Mix 2)","Transparent Watercolor (Opaque 2)","Gouache (Mix 2)","Gouache (Opaque 2)","Acrylic (Mix 2)","Acrylic (Opaque 2)","Fade Watercolor (Mix 2)","Color Changing 1","Color Changing 2","Coarse Pencil","Coarse Pencil (Light)","Bleed Watercolor","Bleed Watercolor (Dark)","Vector Dip Pen","Vector Felt Tip Pen","Expressive Pastel","Canvas Brush","Impasto Brush","Sketch Pencil","Ink Bleed Pen","Matte Pastel","Textured Marker (Square)","Textured Marker (Rectangle)")
    val presets:List<Preset> = names.mapIndexed{i,n->Preset("animame.${i+1}",n,profile(i,n,"animame.${i+1}"))}
    private val ids=presets.associateBy{it.id}
    fun byId(id:String)=ids[id]?:presets.first()
    fun search(q:String)=if(q.isBlank())presets else presets.filter{it.name.contains(q,true)}
    fun byCategory(c:BrushCategory)=presets.filter{it.settings.category==c}
    private fun profile(i:Int,n:String,id:String):BrushSettings{
        val l=n.lowercase(); val cat=when{l.contains("watercolor")||l.contains("gouache")->BrushCategory.WATERCOLOUR;l.contains("pencil")||l.contains("mechanical")||l.contains("sketch")||l.contains("crayon")||l.contains("pastel")||l.contains("charcoal")||l.contains("chalk")->BrushCategory.SKETCH;l.contains("ink")||l.contains("pen")||l.contains("calligraphy")||l.contains("ruling")||l.contains("fountain")||l.contains("ballpoint")->BrushCategory.INK;l.contains("marker")->BrushCategory.MARKER;l.contains("oil")||l.contains("acrylic")||l.contains("brush")||l.contains("paint")->BrushCategory.PAINT;l.contains("hair")||l.contains("braid")||l.contains("fur")->BrushCategory.HAIR;l.contains("grass")||l.contains("leaf")||l.contains("tree")||l.contains("flower")||l.contains("petal")||l.contains("rose")||l.contains("chrysanthemum")->BrushCategory.PLANTS;l.contains("glitter")||l.contains("neon")||l.contains("light")||l.contains("spark")||l.contains("flare")||l.contains("prism")||l.contains("sequin")->BrushCategory.LIGHT;l.contains("dot")||l.contains("pointill")||l.contains("moire")||l.contains("hatch")||l.contains("cross")||l.contains("grid")||l.contains("stripe")->BrushCategory.POINTILLISM;l.contains("eraser")->BrushCategory.ERASER;l.contains("vector")->BrushCategory.VECTOR;l.contains("airbrush")||l.contains("blur")||l.contains("sputter")||l.contains("splash")||l.contains("cloud")->BrushCategory.EFFECTS;l.contains("chain")||l.contains("stitch")||l.contains("lace")||l.contains("knitting")||l.contains("bead")||l.contains("hose")->BrushCategory.MATERIALS;l.contains("outline")->BrushCategory.COMIC;l.contains("cat footprint")||l.contains("dragonfly")||l.contains("gear")||l.contains("crown")||l.contains("star")||l.contains("heart")||l.contains("triangle")||l.contains("hexagon")||l.contains("pentagram")->BrushCategory.STAMP;else->BrushCategory.DIGITAL}
        val algorithm=when{cat==BrushCategory.WATERCOLOUR->BrushAlgorithm.WATER;cat==BrushCategory.ERASER->BrushAlgorithm.ERASER;cat==BrushCategory.LIGHT||cat==BrushCategory.POINTILLISM||cat==BrushCategory.MATERIALS||cat==BrushCategory.STAMP||l.contains("particle")->BrushAlgorithm.PARTICLE;l.contains("airbrush")->BrushAlgorithm.AIRBRUSH;l.contains("blur")||l.contains("blurring")->BrushAlgorithm.BLUR;l.contains("vector")->BrushAlgorithm.VECTOR;l.contains("shadow")->BrushAlgorithm.DOUBLE;l.contains("color")||l.contains("rainbow")||l.contains("neon")->BrushAlgorithm.COLOR;else->BrushAlgorithm.MONO}
        val r=((i*1103515245L+12345L) and 0x7fffffff).toFloat()/0x7fffffff.toFloat(); val base=when(cat){BrushCategory.SKETCH->8f;BrushCategory.INK->10f;BrushCategory.WATERCOLOUR->22f;BrushCategory.PAINT->28f;BrushCategory.MARKER->18f;BrushCategory.HAIR->6f;else->12f}
        return BrushSettings(id,n,cat,algorithm,size=base*(.55f+r*1.35f),opacity=.92f,minSize=if(l.contains("pencil")||l.contains("pen")) .18f else .35f,maxSize=if(l.contains("marker")||l.contains("oil"))1.35f else 1f,fadeStart=if(l.contains("fade")||l.contains("bleed")) .15f else 0f,fadeEnd=if(l.contains("fade")||l.contains("bleed")) .92f else 1f,spacing=when(algorithm){BrushAlgorithm.PARTICLE->.45f;BrushAlgorithm.AIRBRUSH->.22f;else->.12f+r*.18f},aspect=if(l.contains("flat"))2.4f else if(l.contains("fan"))3.5f else 1f,angle=r*360f,rotationFollow=if(l.contains("angle")||l.contains("following"))1f else .15f,jitterPosition=if(l.contains("rough")||l.contains("sputter")||l.contains("particle")) .22f else 0f,jitterSize=if(l.contains("rough")||l.contains("fur")||l.contains("hair")) .22f else .05f,jitterOpacity=if(l.contains("glitter")||l.contains("particle")) .18f else .04f,jitterRotation=if(l.contains("particle")||l.contains("flower")||l.contains("leaf")) .65f else .05f,scatter=if(algorithm==BrushAlgorithm.PARTICLE).55f else if(l.contains("splash")||l.contains("sputter")) .35f else 0f,particleDensity=if(algorithm==BrushAlgorithm.PARTICLE)1.2f+r*2.5f else 1f,particleSize=if(algorithm==BrushAlgorithm.PARTICLE).25f+r*1.2f else 1f,blur=if(algorithm==BrushAlgorithm.BLUR||algorithm==BrushAlgorithm.AIRBRUSH).5f else if(l.contains("bleed")) .12f else 0f,texture=if(l.contains("texture")||l.contains("rough")||cat==BrushCategory.SKETCH).35f else if(cat==BrushCategory.WATERCOLOUR).18f else .04f,textureScale=.7f+r*2.2f,wetness=if(cat==BrushCategory.WATERCOLOUR).65f else 0f,colorMix=if(cat==BrushCategory.WATERCOLOUR).55f else 0f,dragging=if(cat==BrushCategory.WATERCOLOUR).22f else if(l.contains("oil")) .12f else 0f,pressureSize=.65f,pressureOpacity=.25f,speedSize=if(l.contains("speed")) .65f else .12f,speedOpacity=if(l.contains("speed")) .12f else .02f,blendMode=if(cat==BrushCategory.ERASER)"CLEAR" else "SRC_OVER",thinSpacing=l.contains("thin"),pattern=when{l.contains("triangle")->"triangle";l.contains("square")||l.contains("cube")->"square";l.contains("star")||l.contains("pentagram")->"star";l.contains("heart")->"heart";l.contains("diamond")->"diamond";l.contains("hexagon")||l.contains("sequin")->"hexagon";l.contains("petal")||l.contains("flower")->"petal";l.contains("leaf")||l.contains("grass")->"leaf";l.contains("line")||l.contains("stitch")->"line";l.contains("dot")||l.contains("point")->"dot";else->"circle"},colorJitterHue=if(l.contains("color")||l.contains("rainbow")||l.contains("neon")) .35f else 0f,colorJitterSaturation=if(l.contains("color")) .2f else 0f,colorJitterBrightness=if(l.contains("glitter")||l.contains("light")) .25f else 0f)
    }
}
